"""Keep the complete Lean audit imports, owner inventory and thin driver checked."""
from __future__ import annotations

import argparse
import json
from pathlib import Path
import re

try:
    import tomllib
except ModuleNotFoundError:  # Python < 3.11
    tomllib = None

LEAN_ROOT = Path(__file__).resolve().parents[1]
INVENTORY = 'NeuralReversi.AuditModules'
AGGREGATOR = 'NeuralReversi.AuditImports'
DRIVER = 'Audit'
DRIVER_TEXT = 'import NeuralReversi.AuditImports\n\n#eval NeuralReversi.Audit.runProjectAudit\n'
GENERATED_HEADER = (
    '-- Generated by python verification/lean/scripts/audit_modules.py --write, '
    'which verification/lean/check.py runs; not committed.\n'
)


def source_modules(lean_dir: Path) -> list[str]:
    modules = {}
    for path in lean_dir.rglob('*.lean'):
        relative = path.relative_to(lean_dir)
        if '.lake' in relative.parts:
            continue
        parts = relative.with_suffix('').parts
        if any(re.fullmatch(r"[A-Za-z_][A-Za-z0-9_']*", part) is None for part in parts):
            raise ValueError(f'Ambiguous Lean module path: {relative}')
        name = '.'.join(parts)
        key = name.casefold()
        if key in modules:
            raise ValueError(f'Duplicate Lean module identity: {name}')
        modules[key] = name
    for name in (DRIVER, INVENTORY, AGGREGATOR):
        modules.setdefault(name.casefold(), name)
    return sorted(modules.values())


def generated_texts(modules: list[str]) -> dict[str, str]:
    inventory = (
        GENERATED_HEADER
        + 'import Lean\n\nnamespace NeuralReversi.Audit\n\n'
        'def projectModules : List Lean.Name := [\n'
        + ',\n'.join('  `' + name for name in modules)
        + '\n]\n\nend NeuralReversi.Audit\n'
    )
    imports = GENERATED_HEADER + ''.join(
        'import ' + name + '\n' for name in modules if name not in (DRIVER, AGGREGATOR)
    )
    return {
        'NeuralReversi/AuditModules.lean': inventory,
        'NeuralReversi/AuditImports.lean': imports,
    }


_TOML_STRING = re.compile(r'"(?:\\.|[^"\\])*"|\'[^\']*\'')


def _strip_toml_comment(line: str) -> str:
    pos = 0
    for match in _TOML_STRING.finditer(line):
        comment = line.find('#', pos, match.start())
        if comment != -1:
            return line[:comment]
        pos = match.end()
    comment = line.find('#', pos)
    return line if comment == -1 else line[:comment]


def _parse_toml_string(token: str) -> str:
    if token.startswith('"') and token.endswith('"'):
        return json.loads(token)
    if token.startswith("'") and token.endswith("'"):
        return token[1:-1]
    raise ValueError(f'Unsupported TOML string literal: {token}')


def _parse_toml_string_list(raw: str) -> list[str]:
    inner = raw.strip()
    if not (inner.startswith('[') and inner.endswith(']')):
        raise ValueError(f'Malformed TOML array: {raw}')
    body = inner[1:-1]
    if _TOML_STRING.sub('', body).strip(' \t\r\n,'):
        raise ValueError(f'Unsupported TOML array syntax: {raw}')
    return [_parse_toml_string(match.group()) for match in _TOML_STRING.finditer(body)]


def _parse_lakefile_toml(text: str) -> dict:
    data: dict = {}
    current: dict = data
    lines = iter(text.splitlines())
    for raw_line in lines:
        line = _strip_toml_comment(raw_line).strip()
        if not line:
            continue
        array_header = re.fullmatch(r'\[\[\s*([A-Za-z0-9_-]+)\s*\]\]', line)
        if array_header:
            current = {}
            data.setdefault(array_header.group(1), []).append(current)
            continue
        if re.fullmatch(r'\[\s*([A-Za-z0-9_.-]+)\s*\]', line):
            current = {}
            continue
        if '=' not in line:
            continue
        key, value = (part.strip() for part in line.split('=', 1))
        if value.startswith('['):
            while True:
                stripped = _TOML_STRING.sub('', value)
                if stripped.count('[') <= stripped.count(']'):
                    break
                try:
                    value += ' ' + _strip_toml_comment(next(lines)).strip()
                except StopIteration as error:
                    raise ValueError(f'Unterminated TOML array for {key}') from error
            if key == 'roots':
                current[key] = _parse_toml_string_list(value)
        elif value.startswith(('"', "'")):
            current[key] = _parse_toml_string(value)
    return data


def load_toml(text: str) -> dict:
    if tomllib is not None:
        return tomllib.loads(text)
    return _parse_lakefile_toml(text)


def check_build_roots(lean_dir: Path, modules: list[str]) -> None:
    configuration = load_toml((lean_dir / 'lakefile.toml').read_text(encoding='utf-8'))
    libraries = configuration.get('lean_lib', [])
    library = next((value for value in libraries if value['name'] == 'NeuralReversi'), None)
    if library is None:
        raise ValueError('Missing audited Lean library')
    roots = set(library.get('roots', [library['name']]))
    required = {'NeuralReversi', AGGREGATOR} | {name for name in modules if '.' not in name}
    if not required <= roots:
        raise ValueError(
            'Missing default Lean audit/regression roots: ' + ', '.join(sorted(required - roots))
        )


def check_driver(lean_dir: Path) -> None:
    if (lean_dir / 'Audit.lean').read_text(encoding='utf-8') != DRIVER_TEXT:
        raise ValueError(
            'Audit.lean must remain the checked thin import and final audit invocation'
        )


def validate(lean_dir: Path, *, write: bool = False) -> int:
    modules = source_modules(lean_dir)
    check_driver(lean_dir)
    check_build_roots(lean_dir, modules)
    for name, expected in generated_texts(modules).items():
        path = lean_dir / name
        if write:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(expected.encode('utf-8'))
        elif not path.is_file() or path.read_text(encoding='utf-8') != expected:
            raise ValueError(
                f'Stale complete-audit metadata: {name}; '
                'run python verification/lean/scripts/audit_modules.py --write'
            )
    return len(modules)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        '--write',
        action='store_true',
        help='Explicitly regenerate the import and module inventory files',
    )
    args = parser.parse_args()
    try:
        count = validate(LEAN_ROOT, write=args.write)
    except (OSError, ValueError) as error:
        parser.exit(1, f'AUDIT MODULES FAIL: {error}\n')
    print(f'AUDIT MODULES OK ({count} source modules; imports, thin driver and default roots checked)')


if __name__ == '__main__':
    main()
